<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {errorText,id} from './client.mjs';import {contract} from './schema.mjs';import Field from './Field.vue';import Quantity from './Quantity.vue';
const props=defineProps({modelValue:Object,client:Object,base:Object,status:Object,saved:Boolean,readonly:Boolean});const emit=defineEmits(['update:modelValue','pending','busy']);let alive=true;
const endpoint=ref(''),key=ref(''),busy=ref(false),error=ref(''),notice=ref(''),replaceKeys=ref(false);
const probe=ref(null),probing=ref(false);let probeEpoch=0;
async function testConnection(){if(probing.value||!props.saved||pending.value||props.status?.error.value)return;const epoch=++probeEpoch;probing.value=true;error.value='';probe.value=null;try{const result=await props.client.post('/ai/connection-test',{config_revision:props.status.current.value.revision,runtime_generation:props.status.health.value.generation});if(alive&&epoch===probeEpoch)probe.value=result}catch(e){if(alive&&epoch===probeEpoch)error.value=errorText(e)}finally{if(alive&&epoch===probeEpoch)probing.value=false}}
watch(()=>JSON.stringify([props.saved,props.modelValue]),()=>{probeEpoch++;probe.value=null;probing.value=false});
const pending=computed(()=>!!(endpoint.value||key.value));watch(pending,v=>emit('pending',v));
let promptStart=null;
function editPrompt(value){if(promptStart===null)promptStart={prompt:props.modelValue.prompt,backup:props.modelValue.prompt_backup};emit('update:modelValue',{...props.modelValue,prompt:value,prompt_backup:promptStart.prompt,prompt_previous_backup:promptStart.backup})}
const set=(name,value)=>emit('update:modelValue',{...props.modelValue,[name]:value});
async function store(){if(busy.value||props.readonly||!pending.value||!props.base)return;busy.value=true;emit('busy',true);error.value='';notice.value='';let draft={...props.modelValue};
 try{for(const [kind,value] of [['endpoint',endpoint.value.trim()],['key',key.value.trim()]]){if(!value)continue;const result=await props.client.post('/credentials',{...props.base,operation_id:id(),kind,value});if(!alive)return;if(!/^secret:[a-f0-9]{32}$/.test(result.reference))throw Error('INVALID_CREDENTIAL_REFERENCE');draft=kind==='endpoint'?{...draft,endpoint_ref:result.reference}:{...draft,credential_refs:replaceKeys.value?[result.reference]:[...draft.credential_refs,result.reference]};emit('update:modelValue',draft);if(kind==='endpoint')endpoint.value='';else key.value=''}if(alive)notice.value='私密连接信息已写入并带入草稿。保存设置后生效；尚未验证模型连接。'}catch(e){if(alive)error.value=errorText(e)+' 已成功写入的部分保留在草稿中。'}finally{key.value='';if(alive){busy.value=false;emit('busy',false)}}
}
function restore(value){promptStart=null;emit('update:modelValue',{...props.modelValue,prompt:value,prompt_backup:props.modelValue.prompt,prompt_previous_backup:props.modelValue.prompt_backup})}
onBeforeUnmount(()=>{alive=false;endpoint.value='';key.value='';emit('pending',false);emit('busy',false)});
</script>
<template><section aria-label="AI 连接与名称辅助"><label class="sb-toggle-row"><span><strong>启用 AI 名称辅助</strong><small>仅辅助识别；作品身份、版本准入与执行权限仍由原有流程确认。</small></span><input type="checkbox" :checked="modelValue.enabled" :disabled="readonly||busy" @change="set('enabled',$event.target.checked)"></label><section class="sb-form-section"><h4>服务连接</h4><ol class="sb-ai-states"><li>{{modelValue.endpoint_ref&&modelValue.credential_refs.length?'连接信息已私密保存':'尚未保存连接信息'}}</li><li>{{saved?'页面设置与已保存配置一致':'设置尚在草稿中'}}</li><li>{{probe?.state==='MODEL_RESPONDED'?'本次模型请求已成功':probe?.state==='CACHED'?'本次使用缓存，未发送模型请求':'本次尚未确认模型响应'}}</li></ol><p role="status" class="sb-muted">{{modelValue.endpoint_ref&&modelValue.credential_refs.length&&modelValue.model?'连接参数已配置；不代表模型请求已成功。':'连接参数尚未填齐。'}}</p><label>服务地址<input v-model="endpoint" type="password" autocomplete="off" maxlength="4096" :disabled="readonly||busy" :placeholder="modelValue.endpoint_ref?'地址已私密保存；留空保留':'输入 OpenAI 兼容服务地址'"><small>地址只写入私密存储，不回显已保存地址。</small></label><div class="sb-grid"><label>模型名称<input :value="modelValue.model" :disabled="readonly||busy" maxlength="256" placeholder="例如 deepseek-chat" @input="set('model',$event.target.value)"></label><label>服务适配<select :value="modelValue.profile" :disabled="readonly||busy" @change="set('profile',$event.target.value)"><option value="auto">自动</option><option value="deepseek">DeepSeek</option><option value="generic">通用兼容服务</option></select></label></div><label>新密钥<input v-model="key" type="password" autocomplete="new-password" maxlength="4096" :disabled="readonly||busy" placeholder="输入后私密写入，不进入普通配置"></label><label v-if="modelValue.credential_refs.length" class="sb-check"><input v-model="replaceKeys" type="checkbox" :disabled="readonly||busy">用本次密钥替换当前轮换列表（默认追加到末尾）</label><VBtn variant="tonal" :disabled="readonly||busy||!pending||!base" @click="store">{{busy?'正在私密写入…':'应用连接信息到草稿'}}</VBtn><p v-if="pending" class="sb-muted">还有尚未应用的连接输入。先应用，再保存整份设置。</p><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert" class="sb-error">{{error}}</p><div class="sb-actions"><VBtn variant="tonal" :disabled="!saved||!modelValue.enabled||pending||busy||probing||!!status?.error.value" @click="testConnection">{{probing?'正在测试模型…':'测试已保存的模型连接'}}</VBtn></div><p class="sb-muted">使用固定影片标题发送真实模型请求，会消耗少量额度并遵守现有轮换、缓存与冷却。需先保存连接配置并启用 AI；不创建订阅。名称解析预演使用本地规则，不能作为模型连通性验证。</p><p v-if="probe" role="status">{{probe.state==='MODEL_RESPONDED'?'本次模型请求成功，响应通过识别格式校验。':probe.state==='CACHED'?'复用了已缓存结果，本次没有新发模型请求。':'本次未确认模型连接成功。'}} 请求次数：{{probe.result?.attempts||0}}。</p><details v-if="probe" class="sb-technical"><summary>连接测试依据</summary><p>{{probe.result?.reason}} · {{probe.result?.source}} · {{probe.result?.elapsed_ms}} ms</p></details><details class="sb-technical"><summary>密钥轮换顺序 · {{modelValue.credential_refs.length}} 份</summary><ol><li v-for="(credential,index) in modelValue.credential_refs" :key="credential">{{index===0?'首选密钥':'备用密钥 '+index}} <VBtn v-if="index>0" variant="text" :disabled="readonly||busy" @click="set('credential_refs',[credential,...modelValue.credential_refs.filter(c=>c!==credential)])">设为首选</VBtn><VBtn variant="text" color="error" :disabled="readonly||busy" @click="set('credential_refs',modelValue.credential_refs.filter(c=>c!==credential))">停止使用</VBtn></li></ol><p>停止使用只移除草稿中的关联，不删除私密存储；服务端存储预算仍保留。</p></details></section>
 <section class="sb-form-section"><h4>识别提示词</h4><label>当前提示词<textarea class="sb-prompt" rows="12" maxlength="32768" :value="modelValue.prompt" :disabled="readonly||busy" @input="editPrompt($event.target.value)"/></label><details class="sb-technical"><summary>历史版本与恢复</summary><section v-for="[name,title] in [['prompt_backup','最近备份'],['prompt_previous_backup','更早备份']]" :key="name"><h4>{{title}}</h4><template v-if="modelValue[name]"><pre class="sb-prompt-history">{{modelValue[name]}}</pre><VBtn variant="tonal" :disabled="readonly||busy" @click="restore(modelValue[name])">将此版本恢复到草稿</VBtn></template><p v-else>暂无此备份。</p></section><VBtn variant="text" :disabled="readonly||busy" @click="restore(contract.defaults.ai_assist.prompt)">恢复默认提示词到草稿</VBtn></details></section>
 <details class="sb-technical"><summary>识别范围、缓存与请求预算</summary><div class="sb-grid"><Field v-for="name in ['name_assistance_enabled','compatible','proxy','max_attempts','max_concurrency','queue_size','cache_size','notifications','name_recognize_bridge']" :key="name" :name="name" :schema="contract.schemas.AIConfig.properties[name]" :model-value="modelValue[name]" :readonly="readonly||busy" @update:model-value="set(name,$event)"/><Quantity v-for="[name,title] in [['timeout','模型请求超时'],['positive_ttl','成功识别缓存时间'],['negative_ttl','未识别结果缓存时间']]" :key="name" :label="title" :model-value="modelValue[name]" :readonly="readonly||busy" @update:model-value="set(name,$event)"/></div></details>
</section></template>
